module async_fifo #(
  parameter DSIZE = 8,
  parameter ASIZE = 4,
  parameter FALLTHROUGH = "TRUE"
)(
  input  wire             wclk,
  input  wire             wrst_n,
  input  wire             winc,
  input  wire [DSIZE-1:0] wdata,
  output wire             wfull,
  output wire             awfull,

  input  wire             rclk,
  input  wire             rrst_n,
  input  wire             rinc,
  output wire [DSIZE-1:0] rdata,
  output wire             rempty,
  output wire             arempty
);

  reg [DSIZE-1:0] fifo [2**ASIZE-1:0];
  reg [ASIZE-1:0] wptr, rptr;
  reg [ASIZE-1:0] wptr_gray, rptr_gray;
  reg [ASIZE-1:0] wptr_sync, rptr_sync;
  reg [ASIZE:0]  count;
  reg             wfull_reg, rempty_reg;
  reg             awfull_reg, arempty_reg;

  assign wfull = wfull_reg;
  assign awfull = awfull_reg;
  assign rempty = rempty_reg;
  assign arempty = arempty_reg;

  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr <= 0;
      wptr_gray <= 0;
      wfull_reg <= 0;
      awfull_reg <= 0;
    end else if (winc && !wfull_reg) begin
      fifo[wptr] <= wdata;
      wptr <= wptr + 1;
      wptr_gray <= {wptr[ASIZE-2:0], wptr[ASIZE-1]};
    end
  end

  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr <= 0;
      rptr_gray <= 0;
      rempty_reg <= 1;
      arempty_reg <= 1;
    end else if (rinc && !rempty_reg) begin
      if (FALLTHROUGH == "TRUE") begin
        rdata <= fifo[rptr];
      end
      rptr <= rptr + 1;
      rptr_gray <= {rptr[ASIZE-2:0], rptr[ASIZE-1]};
    end
  end

  always @(posedge wclk) begin
    wptr_sync <= wptr_gray;
  end

  always @(posedge rclk) begin
    rptr_sync <= rptr_gray;
  end

  always @(wptr_sync or rptr_sync) begin
    count <= wptr_sync - rptr_sync;
    if (count == 2**ASIZE - 1) begin
      wfull_reg <= 1;
    end else begin
      wfull_reg <= 0;
    end
    if (count > 2**ASIZE - 2) begin
      awfull_reg <= 1;
    end else begin
      awfull_reg <= 0;
    end
    if (count == 0) begin
      rempty_reg <= 1;
    end else begin
      rempty_reg <= 0;
    end
    if (count < 2) begin
      arempty_reg <= 1;
    end else begin
      arempty_reg <= 0;
    end
  end

  if (FALLTHROUGH != "TRUE") begin
    always @(posedge rclk or negedge rrst_n) begin
      if (!rrst_n) begin
        rdata <= 0;
      end else if (rinc && !rempty_reg) begin
        rdata <= fifo[rptr];
      end
    end
  end

endmodule
